from wslib import *

# roles: ctx (context), prem (reason), evid (evidence/example), analogy (comparison),
#        counter (opposing view), ic (intermediate conclusion), conc (main conclusion)

QUESTIONS = [
dict(n=1, orig=1, answer='A', type='Main conclusion',
     passage=[('evid', '11% of nurses across the country would like to leave the profession. However, this figure rises to 39% amongst nurses who are working alternating shift systems, which mix day, evening and night shifts. It was found that many nurses preferred one type of shift most of the time, whether that involved working early, late or through the night.'),
              ('conc', 'Employers should urgently review staffing arrangements to avoid the compulsory, alternating patterns.'),
              ('prem', "This would make nurses' working hours more compatible with their social and family lives. A further benefit would be a reduction in the cost of training new nurses to replace those leaving.")],
     stem='What is the best expression of the main conclusion of this argument?',
     options={'A': 'The health service should adapt shift patterns to suit nurses in order to retain staff.',
              'B': 'Alternating shift systems cause nurses to want leave the health service.',
              'C': 'Many nurses prefer a regular pattern of work.',
              'D': 'Some nurses would like to leave the profession no matter what their shift pattern.',
              'E': '61% of nurses prefer alternating shift patterns.'},
     right='The “should” sentence: employers should drop alternating shifts. A rewords it, and “retain staff” matches the benefit of fewer nurses leaving.',
     why={'B': 'A reason drawn from the 39% figure, not the recommendation. “Cause” also overstates a link.',
          'C': 'Evidence: “many nurses preferred one type of shift”.',
          'D': 'Hinted at by the 11% figure, but it is a side point, not what the argument argues for.',
          'E': 'Bad maths: 39% wanting to leave does not mean 61% prefer alternating shifts.'},
     gap='Look for “should”. The figures and the benefits are all there to back that one recommendation.'),

dict(n=2, orig=3, answer='C', type='Flaw',
     passage=[('evid', 'Some recent films have been very expensive to make, but have not been the big box-office hits that would have justified the expense. At the same time, there have been films made very cheaply which have been received with both huge critical and popular acclaim. Indeed, some directors who have made successful low-budget films have gone on to make unsuccessful but expensive films.'),
              ('conc', 'It is obvious then that if directors want to make popular films, they should stick to low budgets.')],
     stem='Which one of the following is the best statement of the flaw in the argument above?',
     options={'A': 'Critics are often wrong in their predictions about the popularity of films.',
              'B': 'The cost of making a film is normally greater than its original budget.',
              'C': 'The cost of a film need not be the factor that determines its popularity.',
              'D': 'The popularity of a film would justify a high level of expense in making it.',
              'E': 'The public does not necessarily know whether a film has been expensive or cheap to make.'},
     right='A few examples of cheap hits and expensive flops do not show that the budget <b>causes</b> success. Story, actors or luck could matter more.',
     why={'A': 'Critics’ predictions are never part of the argument.',
          'B': 'Going over budget is irrelevant: cheap films would still be cheaper.',
          'D': 'About whether expense is justified, not about what makes a film popular.',
          'E': 'Viewers need not know the cost for cost to affect a film. It misses the real gap.'},
     gap='“Some” examples, then “it is obvious” about all directors: check whether the link is really cause and effect.'),

dict(n=3, orig=4, answer='E', type='Draw a conclusion',
     passage=[('ctx', 'It is clear that the world is getting warmer.'),
              ('prem', 'The only thing that could slow down this process of global warming, and avert ecological disaster, would be an immediate switch to green technologies.'),
              ('prem', 'If global warming continues at the present rate, some species will be unable to live in the warmer conditions.'),
              ('evid', 'They will need to move to cooler places than they now occupy, for example closer to the poles, or higher up mountains. Not all of these species will be able to reach cooler climates, because of the long distances they would have to travel. Some of those that could move would end up in overcrowded habitats, which would make successful breeding impossible.')],
     stem='Which one of the following can be drawn as a conclusion from the above passage?',
     options={'A': 'Most species require cool habitats for successful breeding.',
              'B': 'Many species will be able to adapt to living in warmer climates.',
              'C': 'Endangered species will survive if we switch to green technologies.',
              'D': 'It is not possible to avert the ecological disaster caused by global warming.',
              'E': 'Unless we switch immediately to green technologies, some species will not survive.'},
     right='Only an immediate switch can slow warming. Without it, warming carries on and some species cannot live, move or breed. So no switch means some species die out.',
     why={'A': '“Most species” is too strong. Breeding fails because of overcrowding, not a need for cool habitats.',
          'B': 'Contradicts the passage: some species “will be unable to live in the warmer conditions”.',
          'C': 'The switch is <b>needed</b> to slow warming, not enough to <b>guarantee</b> survival.',
          'D': 'Contradicts the passage: an immediate switch could avert disaster.'},
     gap='“The only thing that could” sets up a must-have condition. The conclusion will be an “unless” statement.'),

dict(n=4, orig=5, answer='B', type='Assumption',
     passage=[('ctx', 'Cannabis smoking is widespread, even though it is illegal.'),
              ('prem', 'It is also more dangerous to health than most people realise.'),
              ('conc', 'If we want to reduce the use of cannabis, it should be legalised.'),
              ('prem', 'People do not turn away from dangerous habits unless they are fully aware of the damage these habits can cause.'),
              ('analogy', 'We should have learnt this lesson from the example of tobacco smoking, which has declined dramatically because people have seen that it results in deaths from lung cancer.')],
     stem='Which one of the following is an assumption underlying the above argument?',
     options={'A': 'People who still smoke tobacco are unaware that it can affect their health.',
              'B': 'Unless cannabis smoking is legalised, its dangers will not be widely known.',
              'C': 'If tobacco smoking had been illegal, it would have been less widespread.',
              'D': 'There has been insufficient research on the damage caused by cannabis smoking.',
              'E': 'Cannabis users are motivated by the fact that they are engaging in an illegal activity.'},
     right='The reasons are about awareness, the conclusion is about legalising. The missing link: legalising is what makes the dangers known.',
     why={'A': 'Not needed. The argument is about people who gave up once they knew, not those who still smoke.',
          'C': 'Not needed, and it would back keeping cannabis illegal.',
          'D': 'Not needed. The problem is what the public realises, not how much research exists.',
          'E': 'A different reason to legalise. The argument works through awareness of danger, not thrill.'},
     gap='Spot the jump: “people must know the dangers” → “so legalise”. The assumption joins those two.'),

dict(n=5, orig=9, answer='E', type='Strengthen',
     passage=[('prem', 'If children are sitting in rows in a classroom, the teacher can have eye contact with all of them while she is explaining something to them. This is not always possible if they are sitting in groups around tables. Also, when they look up, instead of seeing the child opposite in a group and being tempted to talk, they see the teacher.'),
              ('ic', 'So, sitting in rows helps children to concentrate better on their work'),
              ('conc', 'and should therefore be the standard arrangement in every school classroom.')],
     stem='Which one of the following, if true, would most strengthen the above argument?',
     options={'A': 'Rows of desks take up no more classroom space than tables.',
              'B': 'Some children are easily distracted whether they sit in rows or in groups.',
              'C': 'Sitting in groups of between four and seven makes discussion work easier.',
              'D': 'Traditionalists argue that teaching the whole class in rows is best.',
              'E': 'If desks are arranged in rows, children can all see visual aids more easily.'},
     right='Another real benefit of rows for learning: everyone faces the front and can see what is being shown. That adds to the case.',
     why={'A': 'Only says rows are no worse on space. It adds nothing about learning or concentration.',
          'B': 'If some are distracted either way, rows make less difference: this slightly weakens.',
          'C': 'A benefit of groups: this weakens.',
          'D': 'An appeal to opinion. What traditionalists think is not evidence that rows work.'},
     gap='To strengthen, add a new reason that points the same way as the passage (rows help children learn).'),

dict(n=6, orig=10, answer='C', type='Flaw',
     passage=[('evid', '"There are more police officers than ever before in the history of this country. We have more police officers and more community support officers.'),
              ('conc', 'That is why, last week, crime was down.'),
              ('evid', 'Crime is down 30 per cent."')],
     stem='Which of the following states the flaw in the argument above?',
     options={'A': "Community support officers don't have the same powers as police officers.",
              'B': 'Crime levels can be measured in different ways.',
              'C': 'Crime could have fallen if there had been no increase in policing.',
              'D': 'The fact that crime was down last week does not mean it will stay down.',
              'E': 'Having more police officers may mean more crime is being detected.'},
     right='Two things happened together, so the speaker says one caused the other. Crime might have fallen anyway, for some other reason.',
     why={'A': 'True or not, it does not touch the jump from “more officers” to “that is why crime fell”.',
          'B': 'Too vague. It does not say what is wrong with linking police numbers to the fall.',
          'D': 'The claim is only about last week, not about the future.',
          'E': 'More detection would push recorded crime <b>up</b>, so it does not explain a fall.'},
     gap='“That is why” after two facts: ask whether the first really caused the second.'),

dict(n=7, orig=11, answer='C', type='Main conclusion',
     passage=[('ic', 'The differences between human beings are sometimes more striking than the similarities.'),
              ('evid', 'There is a minority of people who, driven by a competitive urge to be the first or the best, undertake ambitious expeditions involving severe physical deprivations, high risk of fatality, and extreme isolation. Compare these people to the majority who prefer an easy, risk free life of comfort'),
              ('ic', 'and we can see that one human being can be as different from another in their behaviour as two different species of animal.'),
              ('conc', 'Any attempt to form general rules about human behaviour needs to bear this variation in mind.')],
     stem='Which one of the following best expresses the conclusion of the passage above?',
     options={'A': 'Members of the human race can be as different in their behaviour as two separate species of animal.',
              'B': 'Humans who take risks in the interests of achieving unusual feats are untypical.',
              'C': 'Variation in human behaviour makes it difficult to generalise.',
              'D': 'Differences between people can be more striking than similarities.',
              'E': 'Human beings are superior to all other animals.'},
     right='The last sentence: general rules about human behaviour must allow for the variation. In other words, the variation makes generalising hard.',
     why={'A': 'An intermediate conclusion (“we can see that…”) used to support the last sentence.',
          'B': 'A detail of the example (a “minority”), not the point it makes.',
          'D': 'The opening claim, which the example supports on the way to the conclusion.',
          'E': 'Never said. Animals only appear in a comparison.'},
     gap='“We can see that…” gives an intermediate step. Ask what it is used for: the final sentence.'),

dict(n=8, orig=15, answer='B', type='Draw a conclusion',
     passage=[('prem', 'Similar effects have similar causes. The problem is deciding when one set of effects sufficiently resembles another to infer a similar cause.'),
              ('counter', 'You say that the universe resembles a man-made object like a house, so its cause must also be similar, an intelligent designer, resembling human beings.'),
              ('prem', 'But is the universe so like a house? It seems to resemble an animal or vegetable just as closely, so why should its origin not lie in reproduction or some vegetative process?'),
              ('evid', 'The universe contains many classes of effects and objects, all with their different causes.'),
              ('ic', 'There seems to be no compelling reason for concluding that the universe as a whole resembles one of these classes of effects or objects more closely than another.')],
     stem='Which one of the following is a conclusion that can reliably be drawn from the above reasoning?',
     options={'A': 'The universe bears no resemblance to a man-made object like a house.',
              'B': 'The inference that the universe and man-made objects have similar causes is not justified.',
              'C': 'The world resembles a vegetable more closely than a house.',
              'D': 'The universe is not the result of intelligent design.',
              'E': 'The most likely origin of the universe is a reproductive process.'},
     right='The universe is no more like a house than like an animal or plant. So “it is like a house, so it has a house-like cause” is not justified.',
     why={'A': 'Too strong. It resembles a house, just no <b>more</b> than other things.',
          'C': 'Contradicts “just as closely”.',
          'D': 'Too strong. The passage attacks the <b>argument</b> for a designer; it does not prove there is none.',
          'E': 'Too strong. Reproduction is only offered as “why not?”, equally likely, not most likely.'},
     gap='When a passage knocks down an argument, the safe conclusion is “that argument fails”, not “its conclusion is false”.'),

dict(n=9, orig=16, answer='A', type='Assumption',
     passage=[('ctx', 'At first glance, there is no phenomenon creepier than crop circles - huge geometric designs that appear in fields overnight seemingly without cause, explanation or reason.'),
              ('counter', 'UFO enthusiasts are quick to supply all three, by attributing the patterns to alien visitors seeking to communicate with humans, using laser beams or other advanced technology to flatten the crops.'),
              ('conc', 'These fanciful claims can fortunately be dismissed thanks to two quite mundane observations.'),
              ('evid', 'Firstly, ordinary Earth-born individuals have repeatedly demonstrated how to produce the effects with nothing more elaborate than a rope and a plank.'),
              ('analogy', 'Secondly, there is a clear parallel for the phenomenon in the form of urban graffiti. Sneaking into fields to make crop circles is simply a rural variation of a widespread and well-documented human urge.')],
     stem='Which one of the following is an implicit, underlying assumption that is made by the above argument?',
     options={'A': 'Where two explanations compete we should accept the more ordinary one.',
              'B': 'There is nothing difficult or technical about producing crop circles.',
              'C': 'Alien visitors would not try to communicate with humans by flattening crops.',
              'D': 'No visits from intelligent aliens have as yet been documented.',
              'E': 'The appearance overnight of huge geometrical designs is creepy if it can not be explained.'},
     right='The evidence only shows humans <b>could</b> make the circles. To dismiss aliens on that basis, you must prefer the ordinary explanation.',
     why={'B': 'More or less stated (a rope and a plank), and it still only shows humans could do it.',
          'C': 'Not needed. The aliens are dismissed because a mundane cause exists, not because they wouldn’t try.',
          'D': 'Not needed. The argument is about crop circles, not alien visits in general.',
          'E': 'About why they seem creepy, which is just the opening. The reasoning does not rely on it.'},
     gap='“Can be done by people” is not “was done by people”. Find the rule that bridges the two.'),

dict(n=10, orig=17, answer='C', type='Weaken',
     passage=[('ctx', 'When you install a burglar alarm in your home, you do so presumably because the cost of the alarm is less than the expected benefits.'),
              ('prem', 'The cost of a burglary, if one occurs, is likely to be much higher than the cost of fitting an alarm. A clearly visible box on an outside wall of an alarmed house alerts and discourages potential thieves.'),
              ('ic', "Because your house is less likely to be burgled, your neighbour's house may be more vulnerable."),
              ('conc', 'Therefore, while there may be little impact on overall crime levels, expensive security devices reduce crimes against those with the devices but increase crimes against those without.')],
     stem='Which one of the following, if true, would most weaken the above argument?',
     options={'A': 'For similar houses, a higher percentage of those without intruder alarms are burgled than those with alarms.',
              'B': 'As the percentage of houses with intruder alarms increased from 40% to 90%, house burglary rates fell by 60% and there was a rise in street muggings of 100%.',
              'C': 'Burglars perceive an alarm as a signal that there are items well worth stealing in a house, while no alarm indicates less valuable contents.',
              'D': 'Only 60% of houses with alarms set the alarm every day.',
              'E': 'Burglars know that 25% of all visible alarm boxes are fakes, but cannot tell the fake from the genuine.'},
     right='If an alarm box says “valuables inside”, it may attract burglars, not put them off. Then alarms need not reduce crime against their owners.',
     why={'A': 'Alarmed houses burgled less: this strengthens.',
          'B': 'Crime moved elsewhere (muggings) rather than vanishing. That fits “little impact on overall crime”.',
          'D': 'The argument relies on the visible box putting thieves off, set or not.',
          'E': 'Thieves can’t spot fakes, so every box still deters: this strengthens.'},
     gap='The argument hangs on “a visible box discourages thieves”. Attack that link.'),

dict(n=11, orig=21, answer='A', type='Flaw',
     passage=[('conc', 'It would be a good idea if the police force was separated into two divisions, one for proper policing i.e. protecting citizens and upholding law and order, and the other for road traffic.'),
              ('ic', 'This second division could be combined with traffic wardens'),
              ('prem', 'as basically they are doing a similar job: obtaining money from road users.'),
              ('prem', 'Perhaps then there would be a proper focus put on catching criminals and protecting the law-abiding public, and we would have a police force doing the job they were actually intended to do.')],
     stem='Which one of the following best describes the flaw in the above argument?',
     options={'A': 'It overlooks the fact that many traffic offences are both criminal and a serious danger to the public.',
              'B': 'It rests on the false assumption that the police do not protect citizens or catch criminals.',
              'C': 'It ignores the fact that traffic wardens and the police have different duties and different powers.',
              'D': 'It wrongly equates protecting citizens with catching criminals.',
              'E': 'It implies that the police once did the job they were supposed to do.'},
     right='It treats road policing as just “obtaining money”, not “proper policing”. But dangerous and drunk driving are crimes that put the public at risk.',
     why={'B': 'Too strong. It only says the focus could be better, not that police do none of it.',
          'C': 'A practical detail. The claim is only that the jobs are “basically” similar.',
          'D': 'It lists both as parts of proper policing. It never says they are the same thing.',
          'E': 'Not implied, and even if it were, it would not damage the reasoning.'},
     gap='Check the split the argument relies on: is traffic policing really separate from protecting the public?'),

dict(n=12, orig=22, answer='B', type='Parallel reasoning',
     passage=[('prem', 'If you practise playing a musical instrument, your playing will get better.'),
              ('ic', 'I have not practised playing the piano, so my playing has not got better.'),
              ('ctx', 'I have an exam in two month’s time.'),
              ('conc', 'So I must practise every day if I want to do well.')],
     stem='Which of the following most closely parallels the reasoning in the argument?',
     options={'A': 'If you practise playing the cello your playing will get better. Dawn has not practised much but her playing has got better so she must have done enough. She may even pass her Grade III exam next month.',
              'B': 'If you work hard at a sport, you will become better. I have not worked hard at my trampolining, so I have not become better. There is a competition next month. So I must work hard if I want to do well.',
              'C': 'If you work hard at running you will get faster. I have worked hard to get faster, and I have started winning races. There is a race next week. If I want to win it I must keep practising.',
              'D': 'People who practise a craft get better at that craft. All master craftsmen and women have put long hours of practice into their art. It is impossible to become an expert without practising.',
              'E': 'Practise makes perfect. I have practised hard on my violin so I should soon be perfect. I have a competition coming up soon which I fully expect to win.'},
     right='Step for step the same: if A then B; not A, so not B; an event is coming; so I must do A to do well.',
     why={'A': 'Not A but B happened anyway, so A must have been enough. A different (and odd) pattern.',
          'C': 'Starts from “I have done A”, not “I have not done A”.',
          'D': 'A general claim backed by examples, ending “impossible without practice”. No personal not-A, not-B step.',
          'E': '“I have done A, so B will follow”: the opposite middle step, and no “must” at the end.'},
     working_title='Working: strip it to a skeleton',
     working=f"""<p class="skel">Original: if <b>A</b> (practise) then <b>B</b> (get better) {ar('pen')} not A, so not B {ar('pen')} event coming (exam) {ar('pen')} so I <b>must do A</b> to do well.</p>
<div class="map">
<div><b>B</b><span>If A (work hard) then B (get better) → not A, so not B → competition coming → must work hard to do well. {tick()} Same shape, even the same slip.</span></div>
<div><b>A</b><span>If A then B → not much A, yet B → so she did enough A. Starts from B happening. {cross()}</span></div>
<div><b>C</b><span>If A then B → I did A, and B is happening → race coming → keep doing A. Uses “did A”, not “didn’t”. {cross()}</span></div>
<div><b>D</b><span>A gives B → all experts did A → impossible to get B without A. No “I”, no event. {cross()}</span></div>
<div><b>E</b><span>A gives B → I did A, so B soon → expect to win. Positive prediction, no “must”. {cross()}</span></div>
</div>
{note('The original is actually flawed (you could improve without practising). A parallel copies the flaw too, so look for “not A, so not B”.', 'tip')}"""),

dict(n=13, orig=23, answer='D', type='Principle',
     passage=[('conc', 'Legislation is needed in order to prevent the abuse of genetic testing by insurance companies.'),
              ('ctx', 'New genetic tests may reveal how likely an individual is to suffer from certain debilitating or fatal conditions in later life.'),
              ('prem', 'Without legislation, insurance companies might make such tests compulsory and make those at risk pay more for insurance.'),
              ('ic', 'This would be unfair.'),
              ('prem', 'We do not choose our genes; we are born with them. People should not be penalised for things over which they have no control.')],
     stem='Which one of the following best illustrates the principle underlying the above argument?',
     options={'A': 'Kylie did not deliberately get her accounts wrong, but she should pay the fine anyway. She should have made sure the accounts were right.',
              'B': 'Some people have lost everything in the flood. Their insurance companies are responsible for their losses. Therefore the Government should not help out.',
              'C': 'Philip should not receive any help paying his debts, however sorry one may be for him. He knew in advance that his business venture was very risky.',
              'D': "Late payment normally incurs a fine. But Jamuna's payment was held up because postal workers were on strike, so she should not be made to pay the fine.",
              'E': 'Three people were not properly informed of possible financial losses when they joined the scheme. Their financial advisors should lose their professional licences.'},
     right='The postal strike was outside Jamuna’s control, so she should not be fined. That is exactly “don’t penalise people for what they can’t control”.',
     why={'A': 'Kylie is penalised because she <b>could</b> have checked. The opposite case.',
          'B': 'About who should pay for losses, not about penalties or control.',
          'C': 'Philip chose the risk, so he is refused help. It never says to spare someone with no control.',
          'E': 'Punishing advisers who were at fault. Nothing about sparing those who had no control.'},
     working_title='Working: write the principle first',
     working=f"""<p class="skel">Genes are not chosen {ar('pen')} charging people more for them would be unfair {ar('pen')} we need a law to stop it.<br>
So the principle: <b>people should not be penalised for things over which they have no control</b>.</p>
<div class="map">
<div><b>D</b><span>Payment late because of a strike (no control) → should not pay the fine. {tick()} Same principle, new setting.</span></div>
<div><b>A</b><span>Not deliberate, but she could have checked → fine her. Penalises, and she had control. {cross()}</span></div>
<div><b>B</b><span>Insurers are responsible → no Government help. About who pays. {cross()}</span></div>
<div><b>C</b><span>He knew the risk (had control) → no help. Not about sparing anyone. {cross()}</span></div>
<div><b>E</b><span>Advisers at fault → lose licences. Punishing fault, not sparing the blameless. {cross()}</span></div>
</div>
{note('The principle is often stated in the passage itself. Here it is the last sentence.', 'tip')}"""),

dict(n=14, orig=27, answer='E', type='Main conclusion',
     passage=[('ctx', "Britain's property market is in the midst of a full-scale slump with house prices falling at their fastest rate in 15 years, according to a new study."),
              ('counter', 'But why is there an assumption that continuing rises in house prices is a good thing?'),
              ('conc', 'Why not see the fall in house prices as a welcome change?'),
              ('prem', 'House prices as a percentage of income are grossly overpriced. Low interest rates and cheap mortgages have led to the property market, particularly in London, being overvalued.'),
              ('ic', 'Surely this will make houses more affordable.'),
              ('prem', 'First time buyers will be happy beneficiaries of a housing slump. Others finding a silver lining in the gloom are those in rural communities for whom a house had seemed simply out of reach.')],
     stem='Which one of the following is the main conclusion of the above argument?',
     options={'A': 'Low interest rates and cheap mortgages have led to an overvaluing of the property market.',
              'B': 'It is always assumed that continually rising house prices are a good thing.',
              'C': 'Rural communities will no longer find buying a house out of reach.',
              'D': 'Surely a slump in prices will make buying a house more affordable.',
              'E': 'We should view the fall in house prices as a good thing.'},
     right='“Why not see the fall… as a welcome change?” is a question that means “we should welcome it”. Everything after explains why.',
     why={'A': 'A reason: prices were too high to begin with.',
          'B': 'The view being challenged, and “always” overstates it.',
          'C': 'A supporting point, made stronger (“no longer”).',
          'D': 'An intermediate step: falling prices help buyers, which is why the fall is good.'},
     gap='Rhetorical questions can carry the conclusion. Turn “Why not…?” into a plain statement.'),

dict(n=15, orig=28, answer='C', type='Draw a conclusion',
     passage=[('evid', 'The average life expectancy in working class areas of London was significantly higher than in similar areas in other major cities in the first half of the nineteenth century. In London during this time drinking tea had become a part of daily life amongst the poor.'),
              ('ctx', 'The reason for this was a combination of availability and cost. Boats bringing tea to the country docked in London and a certain amount was sold off directly to local markets.'),
              ('evid', 'At this time in the rest of the country tea was still regarded as a luxury, consumed only by the better off.')],
     stem='Which one of the following conclusions is best supported by the passage above?',
     options={'A': 'The drinking of tea increases life expectancy.',
              'B': 'Everyone ought to include tea in their daily diet.',
              'C': 'There may be properties of tea which are beneficial to health.',
              'D': 'The growing popularity of tea led to a decrease in the consumption of more harmful drinks, such as gin.',
              'E': 'For the poor tea was a substitute for food.'},
     right='Poor Londoners drank tea and lived longer than the poor elsewhere. That is only a link, so the careful “may be” is all we can say.',
     why={'A': 'Too strong. A link between tea and long life does not prove tea causes it.',
          'B': '“Ought” goes far beyond a historical link.',
          'D': 'Gin is never mentioned. A possible explanation, not a conclusion from the passage.',
          'E': 'Never suggested.'},
     gap='A correlation supports a cautious “may”, never a firm “does”.'),

dict(n=16, orig=29, answer='C', type='Assumption',
     passage=[('evid', "A recent study by a drugs company found that the amount of money spent on a specific pill used for the treatment of Alzheimer's disease in the UK showed wide regional variation."),
              ('ctx', "Alzheimer's is a condition associated with the ageing process."),
              ('evid', 'In some areas the expenditure was as low as £1 per head of the population over 65 whereas in others it was as high as £10 per head.'),
              ('prem', 'These pills are the most effective treatment for this condition that is currently available.'),
              ('conc', "Therefore, this is another example of 'post-code lottery' where the effectiveness of treatment for a health condition will depend upon where you live.")],
     stem='Which one of the following is an assumption underlying the above argument?',
     options={'A': "The pills are very successful in halting the progress of Alzheimer's disease.",
              'B': "The drugs company that did the research doesn't have a vested interest in selling the pills.",
              'C': "There are no regional variations in the incidence of Alzheimer's in the 65+ age group.",
              'D': 'There are no regional variations in the number of people in the 65+ age group.',
              'E': "It is not possible to develop Alzheimer's disease below the age of 65."},
     right='Spending is per person over 65, not per patient. If some areas have more over-65s <b>with Alzheimer’s</b>, spending should differ, and there is no lottery.',
     why={'A': 'Not needed. They only have to be the best treatment available.',
          'B': 'Not needed. The argument uses the spending figures, not the company’s opinion.',
          'D': 'Already dealt with: the figures are per head of the over-65s.',
          'E': 'Not needed. A few younger patients would not explain a £1 to £10 gap.'},
     gap='Ask “per head of what?” A fair comparison needs the right group: people who have the disease.'),

dict(n=17, orig=33, answer='C', type='Strengthen',
     passage=[('ctx', 'In a high speed police chase, police drivers sometimes lose sight of the car they are chasing.'),
              ('ic', 'But that’s no reason to give up. All they have to do is take the first left, and then the first left again.'),
              ('prem', 'Pursued drivers are likely to keep taking turns as they come up, as this seems instinctively like the best way to lose someone who is following them. They are not going to turn right as this involves waiting and checking for oncoming traffic.'),
              ('conc', 'Therefore take a couple of left turns and the police car will soon have their criminal in sight once again!')],
     stem='Which of the following, if true, would strengthen this argument?',
     options={'A': 'Car chases tend to end with the pursued driver losing control of their vehicle.',
              'B': 'Drivers in TV car chases tend to turn left rather than right when pursued.',
              'C': 'Police drivers are usually able to sustain faster average speeds over a length of time than other drivers.',
              'D': 'Police drivers usually request overhead assistance from a helicopter when chasing criminals in cars.',
              'E': 'Two left turns might take the criminal where they want to be going.'},
     right='Taking the same turns puts police on the right road. Being faster means they close the gap and “soon” see the car again.',
     why={'A': 'How chases end says nothing about the left-turn trick.',
          'B': 'TV chases are fiction, not evidence of real drivers.',
          'D': 'A different way to track them. It does not support the left-turn method.',
          'E': 'Only “might”, and reaching their destination could let them stop and vanish.'},
     gap='The plan has two parts: same route, then catch up. An option that helps either part strengthens it.'),

dict(n=18, orig=34, answer='C', type='Flaw',
     passage=[('ctx', 'The museum has decided to spend money in the hope of staying profitable and, therefore, remaining open.'),
              ('evid', 'It has opened an expensive new front hall, which is very big and well planned, and will undoubtedly impress new visitors.'),
              ('prem', 'For serious students, however, it has nothing to offer that was not there before. All the scholars who want to do so already use the museum, they will continue to come however artistic the displays may or may not be.'),
              ('ic', 'So, it was a waste to spend so much money on appearances,'),
              ('conc', 'the money should have been spent on improving conditions for those who come to study.')],
     stem='Which one of the following is the best statement of the flaw in the above argument?',
     options={'A': 'The museum cannot be sure that new visitors will be attracted by its new front hall.',
              'B': 'There is no evidence that visitors to museums are interested in the conditions in which the contents are displayed.',
              'C': 'If scholars will continue to come anyway, the museum will not make more money by improving their conditions.',
              'D': 'There is no contact or sympathy between serious scholars and members of the general public in museums.',
              'E': 'It is regular users, and not potential new visitors, to the museum who deserve to be rewarded.'},
     right='The aim is to stay profitable. Scholars come anyway, so spending on them earns nothing. The argument’s own reason undermines its conclusion.',
     why={'A': 'A doubt about the hall would, if anything, support calling it a waste.',
          'B': 'Display conditions for visitors are not the issue. The conclusion is about study conditions.',
          'D': 'Never assumed or relevant.',
          'E': 'A value judgement that backs the conclusion. It is not a flaw.'},
     gap='Hold the argument to its own goal (profit). Does the recommended spending meet it?'),

dict(n=19, orig=35, answer='A', type='Main conclusion',
     passage=[('evid', 'England is set to become the most crowded country in Europe as its population grows by a third over the next 50 years, according to official projections. There are currently some 50 million people in England, but in 50 years this could hit 68 million - 1,349 for every square mile.'),
              ('ctx', 'Opposition political parties, who have obtained the data from the Office for National Statistics, demanded restrictions on migration levels.'),
              ('prem', 'The opposition spokeswoman for immigration said "This demonstrates the real pressure public services are being put under as a result of the failed immigration policy of the present government, which the electorate are increasingly recognising."'),
              ('conc', 'Continued unrestricted population growth will lead to extremist political parties benefiting at the ballot box.')],
     stem='Which one of the following best expresses the main conclusion of the above argument?',
     options={'A': 'Extremist parties will gain political capital from the growth in population.',
              'B': 'England is set to become the most crowded country in Europe over the next 50 years.',
              'C': 'Public services will come under increasing pressure as a result of immigration policy.',
              'D': "The electorate are dissatisfied with the government's immigration policy.",
              'E': 'Opposition parties believe immigration is the sole reason for the projected rise in population in England.'},
     right='The last sentence is the writer’s own claim: population growth will help extremist parties. The figures and the quote lead up to it.',
     why={'B': 'The projection: evidence.',
          'C': 'Part of the spokeswoman’s quote, a reported view used as support.',
          'D': 'Also from the quote (“the electorate are increasingly recognising”): a reason.',
          'E': '“Sole reason” is never said.'},
     gap='Separate what others said (the quote) from what the writer concludes from it.'),

dict(n=20, orig=39, answer='E', type='Draw a conclusion',
     passage=[('ctx', 'Many people who live near to mobile phone masts are worried that radiation from these masts will damage their health. Mobile phones themselves have also been suspected of emitting dangerous levels of radiation, and a report recommended that children should be discouraged from making non-essential calls.'),
              ('evid', 'Emission of radiation from the masts is much lower than that from a mobile phone. A few seconds making a phone call is comparable to 24 hours of exposure from a mast. Radiation from both these sources is below the international guidelines as to what is a dangerous level,'),
              ('prem', 'but no one can yet be certain if these guidelines accurately reflect the level of risk.')],
     stem='Which one of the following can be drawn as a conclusion from the above passage?',
     options={'A': 'People who use mobile phones are putting their health at risk.',
              'B': 'The international guidelines underestimate the risk to health from low levels of radiation.',
              'C': 'The health risk from living near a phone mast is lower than that from using a mobile phone.',
              'D': 'People who live near mobile phone masts overestimate the risks to their health from these masts.',
              'E': 'If extensive use of mobile phones is not harmful to health, radiation from a mast is unlikely to be a risk.'},
     right='A mast gives off far less than a phone. So if a lot of phone use is safe, the much smaller dose from a mast is unlikely to be risky.',
     why={'A': 'Not shown. Phones are below the guidelines; we just can’t be sure the guidelines are right.',
          'B': 'Too strong. The passage only says no one is certain, not that they are wrong.',
          'C': 'Not safe: someone near a mast is exposed 24 hours a day, every day, which may outweigh a few calls.',
          'D': 'Can’t tell. Nobody knows the true risk, so we can’t say they overestimate it.'},
     gap='The uncertainty rules out firm claims. A conditional (“if… then…”) is often the safe conclusion.'),

dict(n=21, orig=40, answer='D', type='Assumption',
     passage=[('conc', 'University education is not a matter of forcing through the largest number of graduates at the lowest possible short-term cost.'),
              ('prem', 'This would not serve the needs of the current generation of students and, even from a narrow economic viewpoint, it would not promote economic prosperity in the long term.'),
              ('analogy', 'It is often a poor economic practice to skimp on the production costs of a product, even when you are only interested in the eventual monetary profit to be made from it.'),
              ('prem', 'But in any event university education has wider purposes than merely the promotion of economic prosperity.')],
     stem='Which of the following is an underlying assumption of the above argument?',
     options={'A': 'The principal purpose of university education is to serve the needs of the present generation of students.',
              'B': 'The principal purpose of university education is to promote the long term economic prosperity of the community.',
              'C': 'The more money the manufacturer spends on the production of a product, the greater the eventual profit is likely to be.',
              'D': 'Policies of cost-cutting are likely to reduce the extent to which the university education will achieve its overall purpose.',
              'E': 'Universities should be managed so as to make a monetary profit, but they should also promote certain non-financial values.'},
     right='The argument rejects cheap mass graduation because it would fail students and the economy. That needs cost-cutting to harm what universities are for.',
     why={'A': '“Principal purpose” is too strong. Students’ needs are one purpose among several.',
          'B': 'Contradicts the passage: education has “wider purposes” than prosperity.',
          'C': '“The more… the greater” is far stronger than “often poor practice to skimp”.',
          'E': 'Monetary profit for universities is never suggested.'},
     gap='Negation test: “cost-cutting will NOT reduce what universities achieve”. Then the argument collapses.'),

dict(n=22, orig=41, answer='B', type='Weaken',
     passage=[('conc', 'The preservation of First Class sections on trains is indefensible.'),
              ('ctx', 'This is not because it is socially divisive, which it is; nor because it is very expensive, which it also is;'),
              ('prem', 'but because it inevitably leads to a relatively poorer service in Standard Class sections of trains.'),
              ('ic', 'Clearly, in order to attract First Class passengers it is necessary to maintain certain levels of discomfort in those compartments which cater to the great majority of travellers.'),
              ('evid', 'There is, for example, a powerful disincentive to make more space generally available on trains, as one of the main inducements to travel First Class is to escape overcrowding and be assured of a seat.'),
              ('prem', 'Yet, additional space would add significantly to the safety and comfort of most passengers.')],
     stem='Which one of the following, if true, would most weaken the above argument?',
     options={'A': 'More people are now using First Class sections on trains than ever before.',
              'B': 'The whole rail service benefits from the increased revenue generated by the high cost of First Class tickets.',
              'C': 'On many trains the First Class section occupies only a small proportion of the total accommodation.',
              'D': 'No one is excluded from travelling in the First Class sections of trains, provided they are prepared to pay the higher fare.',
              'E': 'Some people who travel in First Class sections of trains would not use the trains if there were no First Class sections.'},
     right='If First Class money pays for improvements across the network, it helps Standard Class too. That attacks the one reason given: a poorer Standard service.',
     why={'A': 'More First Class users means even more reason to keep Standard uncomfortable: if anything it strengthens.',
          'C': 'The argument is not about the space First Class takes, but the reason it gives to keep Standard crowded.',
          'D': 'Answers “socially divisive”, which the passage has already set aside.',
          'E': 'Losing a few passengers does not show Standard Class is not made worse.'},
     gap='The passage sets aside two reasons and rests on one. Attack that one.'),

dict(n=23, orig=45, answer='D', type='Main conclusion',
     passage=[('counter', 'Although study leave in the run up to exams is traditional, and benefits well-motivated, organised students,'),
              ('ic', 'recent thinking suggests that it is not the best way to improve results.'),
              ('evid', 'Some students are required to do housework or help in the family business rather than studying. Many others spend time playing computer games, watching daytime TV or hanging around with friends instead of revising. Schools which provide in-school study areas with teacher supervision and a programme of booster revision sessions are getting more A*s and fewer Ds.'),
              ('conc', 'It is time to ditch study leave.')],
     stem='Which one of the following best expresses the main conclusion of the argument?',
     options={'A': 'Many students do not make good use of their study leave.',
              'B': 'Students who work hard find study leave useful.',
              'C': 'Study leave is not the best way for students to gain high results.',
              'D': 'Study leave ought to be abandoned.',
              'E': 'Traditional methods of education need to be updated to improve results.'},
     right='“It is time to ditch study leave” is the recommendation. D says the same thing in plain words.',
     why={'A': 'Evidence: housework, games and TV instead of revising.',
          'B': 'The concession at the start (“Although…”).',
          'C': 'An intermediate conclusion that supports ditching study leave.',
          'E': 'Too broad. The passage is only about study leave.'},
     gap='“It is time to…” is a call to action. The “not the best way” claim is the step before it.'),

dict(n=24, orig=46, answer='E', type='Fill the gap',
     passage=[('ic', 'Land reform is urgently needed in the UK.'),
              ('evid', 'It is well documented that around two-thirds of Britain is owned by just 0.3% of the population. Many of the largest estates have been in the hands of the same families for centuries, and were acquired under outdated feudal laws, often by means of aggression.'),
              ('prem', 'If these families had any sense of social justice in the 21st century they would by now have voluntarily surrendered all but the acreage they needed for personal privacy.'),
              ('conc', '__________________________________ the state should confiscate all excessive land holdings without compensation and redistribute them into the families of workers and taxpayers at affordable prices.')],
     stem='Which of the following phrases, inserted in the blank space, most logically completes the above argument?',
     options={'A': 'In the current economic climate, ...',
              'B': 'On the other hand, ...',
              'C': 'This being the case, ...',
              'D': 'Therefore, on legal grounds, ...',
              'E': 'Since they have not, ...'},
     right='“If they had any sense of justice, they would have given it up.” They haven’t, so the state should take it. E supplies that missing fact.',
     why={'A': 'The economy is never mentioned.',
          'B': 'Signals a contrast, but confiscation follows on from the reasons rather than opposing them.',
          'C': 'The sentence before is an “if” about something that has not happened. There is no “case” to build on.',
          'D': 'The argument is about social justice, not law. The land was in fact acquired under (old) laws.'},
     gap='Read the sentence before the gap carefully. An “if they had… they would have” sentence invites “since they have not”.'),

dict(n=25, orig=47, answer='A', type='Parallel reasoning',
     passage=[('prem', 'All trees have leaves. An oak is a tree.'),
              ('conc', 'Therefore oaks have leaves.')],
     stem='Which one of the following most closely parallels the reasoning used in the argument?',
     options={'A': 'All leaves grow on trees. That plant has leaves. Therefore that plant is a tree.',
              'B': 'All oaks have leaves. That tree has leaves. Therefore that tree is an oak.',
              'C': 'All plants have leaves. That leaf is an oak leaf. Therefore all plants are oaks.',
              'D': 'All trees have leaves. That plant has leaves. Therefore that plant is a tree.',
              'E': 'All trees have leaves. That plant is not a tree. Therefore that plant does not have leaves.'},
     right='Same valid shape: all X are Y; this is an X; so it is Y. Here: anything with leaves is on a tree; this plant has leaves; so it is a tree.',
     why={'B': 'All oaks have leaves; this has leaves; so it is an oak. Runs the rule backwards.',
          'C': 'Jumps from one leaf to “all plants are oaks”. Not even close.',
          'D': 'Same words as the original, but backwards: having leaves does not make you a tree.',
          'E': 'Denies the first part: not a tree, so no leaves. Invalid.'},
     working_title='Working: strip it to a skeleton',
     working=f"""<p class="skel">Original: all <b>X</b> (trees) are <b>Y</b> (have leaves) {ar('pen')} this is an X (oak is a tree) {ar('pen')} so it is <b>Y</b> (has leaves). Valid.</p>
<div class="map">
<div><b>A</b><span>All X (leaves) are Y (grow on trees) → that plant has X (leaves) → so Y (it is a tree). {tick()} Same shape, and valid.</span></div>
<div><b>B</b><span>All X (oaks) are Y (leafy) → this is Y → so X. Starts from the result. {cross()}</span></div>
<div><b>C</b><span>All plants are leafy → one oak leaf → all plants are oaks. Nonsense jump. {cross()}</span></div>
<div><b>D</b><span>All X (trees) are Y (leafy) → this is Y → so X. Starts from the result. {cross()}</span></div>
<div><b>E</b><span>All X are Y → this is not X → so not Y. Denies the start. {cross()}</span></div>
</div>
{note('Don’t match the words. D shares the original’s first sentence but is the classic backwards trap. Check which part each middle sentence matches.', 'trap')}"""),
]
